BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('HBSE-107-1-011','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-02-03。本題考病人自主權利法。本法 2016-01-06 制定公布，自公布後三年（2019-01-06）施行，考試時尚未施行，題目依公布之條文命題。第8條規定預立醫療決定得隨時以書面撤回或變更（選項A正確）；第10條規定意願人得指定醫療委任代理人，於意願人意識昏迷或無法清楚表達意願時代理表達醫療意願（選項B正確）；第14條規定五款特定臨床條件；第16條規定終止、撤除或不施行維持生命治療或人工營養及流體餵養時，應提供病人緩和醫療及其他適當處置，預立醫療決定並非拒絕包括緩和醫療之一切醫療（選項D錯誤）。2019-06-12 修正第15、19條；2021-01-20 修正第10條，僅將醫療委任代理人資格由「二十歲以上具完全行為能力之人」改為「成年且具行為能力之人」；第8、14、16條未曾修正，就本題規定考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0020189'),('SP104-1-38','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-02-07。本題考原住民族工作權保障法第12條：依政府採購法得標之廠商，於國內員工總人數逾一百人者，履約期間僱用原住民人數不得低於總人數百分之一。最後修正公布日：第12條 2001-10-31（制定公布）；本法其後僅於 2015-02-04 修正第3條，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0130006'),('SP105-1-03','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-01-30。本題考性騷擾防治法（2009-01-23 修正後之條文）。考試時條文：第7條規定組織成員、受僱人或受服務人員人數達三十人以上者應訂定性騷擾防治措施（選項A正確）；第21條規定利用權勢或機會為性騷擾者得加重科處罰鍰至二分之一（選項B正確）；第25條之罪須告訴乃論（選項C正確）；第1條規定適用性別工作平等法及性別平等教育法者，除第12、24、25條外不適用本法，並非規範所有場域（選項D錯誤）。現行條文：本法於 2023-08-16 全文修正（第27條等自 2024-03-08 施行），第7條仍為三十人以上應訂定防治措施，第25條之罪仍須告訴乃論，第1條仍規定性別平等教育法及性別平等工作法別有規定者適用各該法律；惟罰鍰改依第27條，權勢性騷擾處新臺幣六萬元以上六十萬元以下罰鍰、其他性騷擾處一萬元以上十萬元以下罰鍰，已無「加重科處罰鍰至二分之一」之規定，選項(B)已不符現行條文。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050074'),('SP105-1-24','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-01-30。本題考 ICF 架構下之身心障礙分類：身心障礙者權益保障法第5條依身體系統構造或功能將身心障礙分為八類（2007-07-11 全文修正公布，第5條自公布後五年即 2012-07-11 施行），選項(B)稱由八大類擴大為十六大類，與條文所定八類不符；其餘選項為 ICF 之理念。第5條其後未再修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050046'),('SP105-2-14','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-07-23。本題考全民健康保險法第10條被保險人之分類：公、民營事業、機構之受僱者屬第一類；低收入戶成員屬第五類；農會及水利會會員屬第三類；服替代役期間之役齡男子屬第四類。最後修正公布日：第10條 2011-01-26（全文修正），其後 2017、2020、2021、2023 年之修正均未涉及第10條，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0060001'),('SP105-2-28','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-07-23。本題考勞工保險條例與國民年金法之比較。選項(D)：勞工保險條例第14條規定月投保薪資依投保薪資分級表申報；國民年金法第11條規定月投保金額依勞工保險投保薪資分級表第一級定之，並隨消費者物價指數累計成長達百分之五時調整，屬定額制，仍正確。選項(A)：勞工保險條例第58條規定請領年齡自 2009 年施行之日起第十年提高一歲、其後每二年提高一歲，2018 年即調整為 61 歲，非 2020 年；選項(B)：勞工保險條例第13條普通事故保險費率為百分之七點五至百分之十三，國民年金法第10條保險費率自百分之六點五起調高至上限百分之十二；選項(C)：勞工保險條例第58條之1為每滿一年按平均月投保薪資百分之零點七七五加計三千元或百分之一點五五擇優，國民年金法第30條為百分之零點六五加三千元或百分之一點三擇優，選項(A)(B)(C)均仍錯誤。最後修正公布日：勞工保險條例第13條 2008-08-13、第14條 1988-02-03、第58條 2008-08-13、第58條之1 2008-08-13；國民年金法第10條 2007-08-08（制定公布）、第11條 2007-08-08（制定公布）、第30條 2011-06-29，本題考試日之後均未再修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0050001'),('SP106-1-04','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-02-18。本題考少年事件處理法第18條第2項。考試時條文（1997-10-29 全文修正公布，至 2019 年前未再修正）：對於少年有監督權人、少年之肄業學校或從事少年保護事業之機構，發現少年有第3條第2款之虞犯事件者，亦得請求少年法院處理之，官方答案(B)當時正確。現行條文：第3條經 2019-06-19 修正，原虞犯事件改列第1項第2款，限於無正當理由經常攜帶危險器械、施用毒品或迷幻物品而尚未觸犯刑罰法律、預備犯罪或犯罪未遂而為法所不罰之行為三種情形；第18條經 2019-06-19、2023-06-21 修正，有監督權人、少年之肄業學校、從事少年保護事業之機關或機構發現少年有第3條第1項第2款之情形者，得通知少年住所、居所或所在地之少年輔導委員會處理之，由少年輔導委員會輔導並評估認由少年法院處理始能保障少年健全之自我成長者，始請求少年法院處理（直接移送或請求少年法院之過渡規定僅適用於 2023-07-01 前），選項(B)已不符現行條文。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=C0010011'),('SP106-1-20','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-02-18。本題考老人福利法施行細則第8條：住宅設施小規模之原則，指興辦事業計畫書所載開發興建住宅戶數為二百戶以下。本施行細則 2007-07-25 全文修正發布，2009-11-19 僅修正第5、16條，第8條其後未再修正，考試時條文與現行條文相同。（老人福利法第33條已於考試前之 2015-12-09 修正為推動社會住宅、排除老人租屋障礙，不再規定小規模、融入社區及多機能原則，惟施行細則第8條迄未配合修正。）官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050038'),('SP106-1-29','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-02-18。本題考兒童及少年福利與權益保障法施行細則第10條安置之順序。考試時條文（2015-11-11 修正發布）：應循下列順序為原則：一、安置於合適之親屬家庭；二、安置於已登記合格之寄養家庭；三、收容於經核准立案之兒童及少年安置及教養機構；四、收容於其他安置機構，官方答案(A)當時正確。現行條文（2020-02-20 修正發布）：應依下列順序為之：一、適當之親屬；二、與兒童及少年有長期正向穩定依附關係之第三人；三、登記合格之寄養家庭；四、核准立案之兒童及少年安置及教養機構；五、其他安置機構。選項(A)之相對順序雖仍相同，但缺漏第二順位「與兒童及少年有長期正向穩定依附關係之第三人」，已不完全符合現行條文。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050010'),('SP106-1-30','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-02-18。本題考兒童及少年福利與權益保障法施行細則第8、9條：早期療育指由社會福利、衛生、教育等專業人員以團隊合作方式，依未滿六歲之發展遲緩兒童及其家庭之個別需求提供服務（選項A正確、選項B「未滿十二歲」錯誤）；發展遲緩兒童須經衛生主管機關認可之醫院評估確認並發給證明（選項C錯誤），再評估之時間得由專業醫師視個案發展狀況建議之（選項D錯誤）。第8條自 2012-07-09 全文修正發布後未再修正，第9條最後於 2015-03-16 修正；其後 2015-11-11 及 2020-02-20 之修正均未涉及第8、9條，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050010'),('SP107-1-18','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-02-03。本題考住宅法第3、4條。考試時條文（2017-01-11 全文修正公布）：第4條規定社會住宅應以直轄市、縣（市）轄區為計算範圍，提供至少百分之三十以上比率出租予經濟或社會弱勢者，另提供一定比率予未設籍於當地且在該地區就學、就業有居住需求者，選項(C)(D)當時正確；第3條規定社會住宅指專供出租之用之住宅及其必要附屬設施，選項(B)「供出租或在政府規範下買賣」錯誤。現行條文：第4條經 2021-06-09、2023-12-06、2026-03-04 修正，已改為提供至少百分之四十比率出租予經濟或社會弱勢者，並提供至少百分之二十比率出租予新婚二年內或育有未成年子女之婚育家庭，選項(C)「百分之三十以上」已不符現行條文；本法於 2017 年後亦已多次修正，選項(A)所稱「新修正的住宅法」已非最新版本。第3條社會住宅仍專供出租，選項(B)仍錯誤。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0070195'),('SW-104-1-07','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-02-07。本題考身心障礙者個人照顧服務辦法第2條用詞定義：友善服務指到宅關懷身心障礙者並支持其社會參與；居家復健由物理治療師、職能治療師或語言治療師於居住處提供復健治療服務；生活重建指於中途致障有生活支持需求之身心障礙者，由專業人員於其重建關鍵期提供心理支持及服務，並非由身心障礙同儕提供（選項C錯誤）；社區居住指以一般社區住宅房舍提供非機構式之居住服務。考試時適用 2012-07-09 訂定發布之條文；2015-05-20 修正第2條係增訂家庭托顧之定義，上述四項定義文字未變，考試時條文與現行條文就本題規定相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050187'),('SW-109-2-37','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2020-08-01。本題考民法第1055條之1審酌子女最佳利益應注意之事項：包括子女之年齡、性別、人數及健康情形（①）、各族群之傳統習俗、文化及價值觀（④）、父母之一方是否有妨礙他方對未成年子女權利義務行使負擔之行為（⑤）、父母保護教養子女之意願及態度（⑥），不包括父母再婚機率及祖父母態度。最後修正公布日：第1055條之1 2013-12-11，本題考試日之後未再修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=B0000001'),('SW-111-2-38','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2022-07-30。本題考聘任學校社會工作師之法源。學生輔導法第3條規定專業輔導人員指具有臨床心理師、諮商心理師或社會工作師證書，由主管機關或學校依法進用從事學生輔導工作者，第11條規定高級中等以下學校主管機關應置專任專業輔導人員（2024-12-18 修正第3、11條，自 2027-01-01 施行，修正前後均有上述規定）；國民教育法考試時第10條規定國民小學及國民中學得置專任專業輔導人員、直轄市、縣（市）政府應置專任專業輔導人員，2023-06-21 全文修正後第21條仍規定專任專業輔導人員之員額編制應依學生輔導法規定；偏遠地區學校教育發展條例第11條規定地方主管機關應於偏遠地區學校置專業輔導人員或社會工作人員（2017-12-06 制定公布，2026-09-23 僅修正第12、15、17條）；精神衛生法考試時第10條及 2022-12-14 全文修正後第6條，僅規定教育主管機關推動學校心理衛生教育或心理健康促進，均無聘任學校社會工作師之規定，選項(C)仍非法源。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=H0070058');
DO $g$ BEGIN
IF (SELECT count(*) FROM swsi_before)<>4800 THEN RAISE EXCEPTION 'count'; END IF;
IF (SELECT count(*) FROM swsi_batch)<>14 THEN RAISE EXCEPTION 'batch size'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_status='unreviewed' AND q.legal_checked_at IS NULL AND q.legal_note IS NULL AND q.legal_source_url IS NULL)<>14 THEN RAISE EXCEPTION 'preimage mismatch'; END IF;
END $g$;
UPDATE public.questions q SET legal_status=b.status, legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz, legal_note=b.note, legal_source_url=b.url
FROM swsi_batch b WHERE q.id=b.id;
DO $a$ BEGIN
IF (SELECT md5(string_agg(concat_ws(chr(31),q.id,q.legal_status,q.legal_note,q.legal_source_url),chr(30) ORDER BY q.id)) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz)<>'729c7d9ecc7b305fd82e46e2754804bc' THEN RAISE EXCEPTION 'postimage mismatch'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b FULL JOIN public.questions q USING(id) WHERE coalesce(b.id,q.id) NOT IN (SELECT id FROM swsi_batch) AND b.row IS DISTINCT FROM to_jsonb(q)) THEN RAISE EXCEPTION 'unrelated change'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b JOIN public.questions q USING(id) WHERE b.id IN (SELECT id FROM swsi_batch) AND (b.row - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url') IS DISTINCT FROM (to_jsonb(q) - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url')) THEN RAISE EXCEPTION 'non-legal field changed'; END IF;
END $a$;
SELECT count(*) FILTER (WHERE q.legal_status='verified_current') verified_10, count(*) FILTER (WHERE q.legal_status='changed') changed_4, count(*) total_14 FROM public.questions q JOIN swsi_batch b USING(id);
COMMIT;
